import {test,expect} from '@playwright/test';
async function image(page,name='first.png'){
 const data=await page.evaluate(()=>{const canvas=document.createElement('canvas');canvas.width=100;canvas.height=80;const c=canvas.getContext('2d');c.fillStyle='#41745f';c.fillRect(0,0,100,80);return canvas.toDataURL().split(',')[1];});
 return {name,mimeType:'image/png',buffer:Buffer.from(data,'base64')};
}
async function revoke(page){
 await page.goto('/child.html#pairing');await page.getByRole('button',{name:'演示家长撤销设备授权',exact:true}).click();await page.getByRole('button',{name:'确认撤销授权',exact:true}).click();
}
async function newCode(page){await page.getByText('原型状态演示',{exact:true}).click();await page.getByRole('button',{name:'模拟家长生成新配对码',exact:true}).click();}
async function navigate(page,tab){await page.evaluate(tab=>location.hash=tab,tab);}
test('pairing locks attempts, expires, consumes code and gates direct routes',async({page})=>{
 await revoke(page);await expect(page.getByRole('button',{name:'连接我的学习空间',exact:true})).toBeDisabled();await newCode(page);
 for(let i=0;i<3;i++){await page.getByLabel('6 位配对码',{exact:true}).fill('000000');await page.getByRole('button',{name:'连接我的学习空间',exact:true}).click();}
 await expect(page.getByRole('button',{name:'连接我的学习空间',exact:true})).toBeDisabled();
 await page.getByRole('button',{name:'模拟家长生成新配对码',exact:true}).click();await page.getByRole('button',{name:'模拟码过期',exact:true}).click();await expect(page.getByRole('button',{name:'连接我的学习空间',exact:true})).toBeDisabled();
 await page.getByRole('button',{name:'模拟家长生成新配对码',exact:true}).click();await page.getByLabel('6 位配对码',{exact:true}).fill('246810');await page.getByRole('button',{name:'连接我的学习空间',exact:true}).click();await expect(page.locator('h1:visible')).toContainText('林同学');
 await navigate(page,'pairing');await page.getByRole('button',{name:'演示家长撤销设备授权',exact:true}).click();await page.getByRole('button',{name:'确认撤销授权',exact:true}).click();await navigate(page,'homework');await expect(page.getByText('配对码已使用',{exact:true})).toBeVisible();await expect(page.locator('.upload-zone')).toHaveCount(0);
});
test('revoking clears photos, correction drafts and pending timers',async({page})=>{
 await page.goto('/child.html#mistakes');await page.getByPlaceholder('写下你的答案和想法').fill('私人草稿');await navigate(page,'homework');await page.locator('input[type=file]').setInputFiles(await image(page));await page.getByLabel('我已经自己试着完成了这些题').check();await page.getByRole('button',{name:'开始检查 · 1 张'}).click();
 await navigate(page,'pairing');await page.getByRole('button',{name:'演示家长撤销设备授权',exact:true}).click();await page.getByRole('button',{name:'确认撤销授权',exact:true}).click();await newCode(page);await page.getByLabel('6 位配对码',{exact:true}).fill('246810');await page.getByRole('button',{name:'连接我的学习空间',exact:true}).click();
 await navigate(page,'homework');await expect(page.locator('.photo-card')).toHaveCount(0);await expect(page.getByLabel('我已经自己试着完成了这些题')).not.toBeChecked();await expect(page.getByRole('button',{name:'开始检查 · 0 张'})).toBeVisible();await navigate(page,'mistakes');await expect(page.getByPlaceholder('写下你的答案和想法')).toHaveValue('');
});
test('rest reminder is optional, acknowledged once and survives navigation',async({page})=>{
 await page.goto('/child.html#home');await page.getByRole('button',{name:'演示到时提醒'}).click();await expect(page.getByText('认真学了一会儿，休息一下吧')).toBeVisible();await page.getByRole('button',{name:'知道了，继续学习'}).click();await navigate(page,'preview');await expect(page.getByText('本次提醒已完成，按自己的节奏学习。')).toBeVisible();await page.getByLabel('开启休息提醒').uncheck();await expect(page.getByText('提醒已关闭，可以继续使用。')).toBeVisible();await expect(page.getByPlaceholder('写下一种物品，或一个想在课堂上问的问题')).toBeEditable();
});
test('photo order and rotated crop change actual image pixels',async({page})=>{
 await page.goto('/child.html#homework');await page.locator('input[type=file]').setInputFiles([await image(page),await image(page,'second.png')]);await page.getByRole('button',{name:'前移第2张',exact:true}).click();await expect(page.locator('.photo-card').first()).toContainText('second.png');await page.getByRole('button',{name:'旋转第1张',exact:true}).click();await page.getByRole('button',{name:'裁剪第1张',exact:true}).click();const dialog=page.getByRole('dialog');
 await expect(dialog.getByRole('button',{name:'保存裁剪',exact:true})).toBeEnabled();await dialog.getByLabel('宽度 (%)',{exact:true}).fill('100');await expect(dialog.getByRole('button',{name:'保存裁剪',exact:true})).toBeDisabled();
 await dialog.getByLabel('左侧 (%)',{exact:true}).fill('0');await dialog.getByLabel('顶部 (%)',{exact:true}).fill('0');await dialog.getByLabel('宽度 (%)',{exact:true}).fill('50');await dialog.getByLabel('高度 (%)',{exact:true}).fill('50');await dialog.getByRole('button',{name:'保存裁剪',exact:true}).click();await expect(dialog).toBeHidden();await expect(page.locator('.photo-card').first()).toContainText('裁剪-40×50.png');await expect.poll(()=>page.locator('.photo-card img').first().evaluate(img=>[img.naturalWidth,img.naturalHeight])).toEqual([40,50]);
});
test('interrupted check retries same batch and cancellation preserves photos',async({page})=>{
 await page.goto('/child.html#homework');await page.locator('input[type=file]').setInputFiles(await image(page));await page.getByLabel('我已经自己试着完成了这些题').check();await page.getByText('检查异常演示',{exact:true}).click();await page.getByLabel('模拟本次检查网络中断').check();await page.getByRole('button',{name:'开始检查 · 1 张'}).click();await expect(page.getByText('检查暂时中断，照片还在')).toBeVisible();await expect(page.getByText(/网络中断示例 · 批次 DEMO-001/)).toBeVisible();await page.getByRole('button',{name:'使用相同批次重试',exact:true}).click();await expect(page.getByText('批次 DEMO-001 · 未调用 AI',{exact:true})).toBeVisible();await expect(page.getByText('检查示例已准备好')).toBeVisible();await page.getByRole('button',{name:'再检查一份作业'}).click();await page.getByRole('button',{name:'开始检查 · 1 张'}).click();await page.getByRole('button',{name:'取消本次检查'}).click();await expect(page.locator('.photo-card')).toHaveCount(1);await expect(page.getByRole('button',{name:'开始检查 · 1 张'})).toBeVisible();
});
test('OCR uncertainty keeps machine answer and prevents premature correction',async({page})=>{
 await page.goto('/child.html#homework');await page.locator('input[type=file]').setInputFiles(await image(page));await page.getByLabel('我已经自己试着完成了这些题').check();await page.getByRole('button',{name:'开始检查 · 1 张'}).click();await expect(page.getByText('检查示例已准备好')).toBeVisible();await page.getByRole('button',{name:'定位示例第1题',exact:true}).click();await expect(page.getByText('原始识别：24 ÷ 6 = 4。该题示例判定正确。')).toBeVisible();await page.getByRole('button',{name:'定位示例第2题',exact:true}).click();await page.getByLabel('识别内容',{exact:true}).fill('家长待核对的文本');await page.getByRole('button',{name:'保存识别核对草稿'}).click();await expect(page.getByText('草稿已记录，需家长确认后采用。机器原始识别保持只读。')).toBeVisible();await page.getByRole('button',{name:'字迹不清，请家长核对'}).click();await expect(page.getByText('第 2 题 · 待家长确认',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'从提示开始订正'})).toHaveCount(0);await expect(page.getByText('机器原始作答：13 厘米',{exact:true})).toBeVisible();
});
test('preview unavailable states clear draft and omit source page',async({page})=>{
 await page.goto('/child.html#preview');const input=page.getByPlaceholder('写下一种物品，或一个想在课堂上问的问题');await input.fill('我的书桌');await page.getByRole('button',{name:'记录我的发现'}).click();await expect(page.getByText('发现已记录。带着你的观察去上课吧！')).toBeVisible();await page.getByLabel('演示教材状态').selectOption('missing');await expect(page.getByText('还没有明天的章节',{exact:true})).toBeVisible();await expect(page.getByText('演示教材 · 第 1 页',{exact:true})).toHaveCount(0);await expect(page.getByText(/示例来源：演示教材/)).toHaveCount(0);await page.getByLabel('演示教材状态').selectOption('expired');await expect(page.getByText('这份教材的授权已到期',{exact:true})).toBeVisible();await page.getByRole('button',{name:'恢复演示教材'}).click();await expect(input).toHaveValue('');await expect(page.getByText('发现已记录。带着你的观察去上课吧！')).toHaveCount(0);
});
test('review help, skip, draft resume and submission retain honest status',async({page})=>{
 await page.goto('/child.html#review');await page.getByRole('button',{name:'提交复习作答'}).click();await expect(page.getByRole('alert')).toContainText('先写下自己的想法');await page.getByRole('button',{name:'不会，需要帮助'}).click();await expect(page.getByText('先画一个长方形，把四条边的长度都标出来，再想一想“围一圈”。')).toBeVisible();await page.getByRole('button',{name:'暂时跳过本题'}).click();await page.getByPlaceholder('先写下你的答案或思路').fill('6+4+6+4=20米');await page.getByRole('button',{name:'退出并保留草稿'}).click();await navigate(page,'pairing');await navigate(page,'review');await page.getByRole('button',{name:'继续上次复习'}).click();await expect(page.getByPlaceholder('先写下你的答案或思路')).toHaveValue('6+4+6+4=20米');await page.getByRole('button',{name:'提交复习作答'}).click();await expect(page.getByText('已提交 · 待家长核对',{exact:true})).toBeVisible();await expect(page.getByText(/提交不等于复习完成或已掌握/)).toBeVisible();
});
test('writing rejects poor images and excludes invalid samples from parent trend',async({page})=>{
 await page.goto('/parent.html#handwriting');await expect(page.getByText('2 份有效样本 · 均值 82',{exact:true})).toBeVisible();await page.getByLabel('示例图片质量').selectOption('unclear');await expect(page.getByText('照片看不清，先不评分',{exact:true})).toBeVisible();await expect(page.locator('meter:visible')).toHaveCount(0);await expect(page.getByText('1 份有效样本 · 均值 80',{exact:true})).toBeVisible();await page.getByLabel('示例图片质量').selectOption('qualified');await page.getByRole('button',{name:'标记本次评分无效'}).click();await expect(page.getByRole('alert')).toContainText('请填写无效原因');await page.getByLabel('无效原因',{exact:true}).fill('纸张类型错误');await page.getByRole('button',{name:'标记本次评分无效'}).click();await expect(page.getByText('1 份有效样本 · 均值 80',{exact:true})).toBeVisible();await expect(page.getByText('已标记无效',{exact:true})).toBeVisible();
});
test('parent tutoring has three hints and separately disclosed full explanation',async({page})=>{
 await page.goto('/parent.html#tutoring');for(let i=0;i<3;i++)await page.getByRole('button',{name:'展开下一步提示',exact:true}).click();await expect(page.getByRole('button',{name:'本题 3 条提示已全部展示'})).toBeDisabled();await expect(page.locator('.tutoring-hints li')).toHaveCount(3);await page.getByRole('button',{name:'查看家长讲解',exact:true}).click();await expect(page.getByText(/26 厘米/)).toBeVisible();
});
test('switching child hides prior evidence and discards unsaved review input',async({page})=>{
 await page.goto('/parent.html#submissions');await page.getByRole('button',{name:'核对详情',exact:true}).first().click();const drawer=page.getByRole('dialog');await drawer.locator('textarea').fill('林同学私有草稿');await drawer.getByPlaceholder('例如：对照原图确认漏写了两条边').fill('未保存的依据');await page.getByRole('button',{name:'关闭此对话框'}).click();await page.getByLabel('切换当前孩子').selectOption('ning');await expect(page.getByText(/还没有作业、复习、课表或报告/)).toBeVisible();await expect(page.locator('.data-grid:visible')).toHaveCount(0);await page.getByLabel('切换当前孩子').selectOption('lin');await page.getByRole('button',{name:'核对详情',exact:true}).first().click();await expect(drawer.locator('textarea')).not.toHaveValue('林同学私有草稿');await expect(drawer.getByPlaceholder('例如：对照原图确认漏写了两条边')).toHaveValue('');
});
